CREATE TABLE relation_predicates (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, key text NOT NULL, label_zh text NOT NULL, label_en text NOT NULL, UNIQUE(workspace_id,key));
CREATE TABLE entities (object_id uuid PRIMARY KEY, workspace_id uuid NOT NULL, type text NOT NULL, canonical_name text NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,type,canonical_name), FOREIGN KEY(workspace_id,object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE);
CREATE TABLE entity_aliases (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, entity_id uuid NOT NULL REFERENCES entities(object_id) ON DELETE CASCADE, alias text NOT NULL, locale text NOT NULL, UNIQUE(entity_id,locale,alias));
CREATE TABLE mentions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, revision_id uuid NOT NULL REFERENCES content_revisions(id) ON DELETE CASCADE, entity_id uuid NOT NULL REFERENCES entities(object_id) ON DELETE CASCADE, locator_json jsonb NOT NULL DEFAULT '{}'::jsonb, confidence real NOT NULL DEFAULT 1 CHECK(confidence>=0 AND confidence<=1), confirmed boolean NOT NULL DEFAULT false, provenance jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX mentions_revision_idx ON mentions(workspace_id,revision_id);
CREATE TABLE relations (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, source_object_id uuid NOT NULL, predicate_id uuid NOT NULL REFERENCES relation_predicates(id), target_object_id uuid NOT NULL, confirmed boolean NOT NULL DEFAULT false, provenance jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,source_object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE, FOREIGN KEY(workspace_id,target_object_id) REFERENCES objects(workspace_id,id) ON DELETE CASCADE, UNIQUE(source_object_id,predicate_id,target_object_id));
CREATE INDEX relations_source_idx ON relations(workspace_id,source_object_id,predicate_id);
CREATE INDEX relations_target_idx ON relations(workspace_id,target_object_id,predicate_id);
